 if other==BASE+'/index.html':other=BASE+'/'
 schema={'@context':'https://schema.org','@type':'ProfilePage','inLanguage':lang,'url':canonical,'mainEntity':{'@type':'Person','name':'Ahmed Abufanas','url':BASE+'/','email':EMAIL,'sameAs':[GITHUB,'https://www.linkedin.com/in/ahmedabufanas/']}} if path.endswith('index.html') else None
 return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc,quote=True)}"><meta name="theme-color" content="#fafbfc"><meta name="color-scheme" content="light dark"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="{lang}" href="{canonical}"><link rel="alternate" hreflang="{'en' if lang=='de' else 'de'}" href="{other}"><link rel="alternate" hreflang="x-default" href="{BASE+'/'+path.removeprefix('en/') if path.removeprefix('en/')!='index.html' else BASE+'/'}"><meta property="og:type" content="{'profile' if schema else 'website'}"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(desc,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:locale" content="{'de_DE' if lang=='de' else 'en_US'}"><meta property="og:image" content="{BASE}/assets/images/ahmed-abufanas.jpg"><meta property="og:image:alt" content="Ahmed Abufanas"><meta property="og:image:width" content="600"><meta property="og:image:height" content="600"><meta property="og:image:type" content="image/jpeg"><link rel="icon" href="{prefix}assets/images/favicon.svg"><script src="{prefix}js/theme-init.js"></script><link rel="stylesheet" href="{prefix}css/style.css"><script defer src="{prefix}js/main.js"></script>{'<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False)+'</script>' if schema else ''}</head><body>{header(lang,prefix,alternate)}{body}{footer(lang,prefix)}</body></html>'''
