 return f'''<figure><a class="chart-button" href="{prefix}assets/images/projects/{p['image']}" data-chart aria-label="{tr(lang,'Grafik vergrößern','Enlarge chart')}: {esc(text(p['short'],lang))}"><img src="{src}" srcset="{srcset}" sizes="{sizes}" width="{info['width']}" height="{info['height']}" alt="{esc(text(p['caption'],lang))}" loading="lazy" decoding="async"><span class="zoom-label">{tr(lang,'Grafik vergrößern','Enlarge chart')} ↗</span></a><figcaption>{text(p['caption'],lang)}</figcaption></figure>'''
